function Invoke-TrakBackup {
    [CmdletBinding()]
    param (
        [Parameter(Mandatory = $true)]
        [ValidateNotNullOrEmpty()]
        [string]$SourcePath,

        [Parameter(Mandatory = $false)]
        [string]$DestinationPath = "$env:TEMP\TrakBackup"
    )

    try {
        Write-Verbose "Creating destination folder: $DestinationPath"
        New-Item -ItemType Directory -Path $DestinationPath -Force | Out-Null
        Copy-Item -Path "$SourcePath\*" -Destination $DestinationPath -Recurse -Force
        Write-Host "[SUCCESS] Backup completed successfully to: $DestinationPath" -ForegroundColor Green
    }
    catch {
        Write-Error "[ERROR] Backup failed: $($_.Exception.Message)"
    }
}
